// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import { IconButton, Button } from '@carbon/react';
import { Edit } from '@carbon/icons-react';
import '@carbon/react/css/fonts.css';
import '@carbon/react/css/icons.css';
import '@carbon/react/scss/components/button/button.scss';

function App() {
  return (
    <div style={{
      display: 'flex',
      gap: '32px',
      background: '#0043CE',
      padding: '32px',
      color: 'white'
    }}>
      {/* Carbon IconButton (buggy padding) */}
      <IconButton
        renderIcon={Edit}
        iconDescription="Edit"
        tooltipPosition="bottom"
      />

      {/* Legacy Button hasIconOnly for comparison */}
      <Button
        hasIconOnly
        renderIcon={Edit}
        iconDescription="Edit"
      />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
